3	import { useEffect, useRef, useState } from "react";
4	import dynamic from "next/dynamic";
5	import Link from "next/link";
6	import { useRouter } from "next/navigation";
7	import worldFeatures from "@/data/world-features.json";
8	
9	type GlobeMethods = {
10	  pointOfView: (
11	    view: { lat?: number; lng?: number; altitude?: number },
12	    transitionMs?: number
13	  ) => void;
14	  controls: () => {
15	    autoRotate?: boolean;
16	    autoRotateSpeed?: number;
17	  };
18	};
19	
20	type GeoCoordinate = [number, number];
21	type PolygonCoordinates = GeoCoordinate[][];
22	type MultiPolygonCoordinates = PolygonCoordinates[];
23	
24	type CountryFeature = {
25	  properties: {
26	    name?: string;
27	    iso_a3?: string;
28	    NAME?: string;
29	    ADMIN?: string;
30	    ISO_A3?: string;
31	  };
32	  geometry: {
33	    type: "Polygon" | "MultiPolygon";
34	    coordinates: PolygonCoordinates | MultiPolygonCoordinates;
35	  };
36	};
37	
38	type CountryLabel = {
39	  lat: number;
40	  lng: number;
41	  name: string;
42	  iso_a3: string;
43	  size: number;
44	};
45	
46	const Globe = dynamic(() => import("react-globe.gl"), {
47	  ssr: false
48	});
49	
50	const countries = (
51	  "features" in worldFeatures ? worldFeatures.features : worldFeatures
52	) as CountryFeature[];
53	
54	function getCountryName(feature: CountryFeature) {
55	  return (
56	    feature.properties.name ??
57	    feature.properties.NAME ??
58	    feature.properties.ADMIN ??
59	    "Unknown"
60	  );
61	}
62	
63	function getCountryCode(feature: CountryFeature) {
64	  return feature.properties.iso_a3 ?? feature.properties.ISO_A3 ?? "UNK";
65	}
66	
67	function getRingArea(ring: GeoCoordinate[]) {
68	  let area = 0;
69	
70	  for (let index = 0; index < ring.length; index += 1) {
71	    const [x1, y1] = ring[index];
72	    const [x2, y2] = ring[(index + 1) % ring.length];
73	    area += x1 * y2 - x2 * y1;
74	  }
75	
76	  return area / 2;
77	}
78	
79	function getLargestRing(feature: CountryFeature) {
80	  const polygons =
81	    feature.geometry.type === "Polygon"
82	      ? [feature.geometry.coordinates as PolygonCoordinates]
83	      : (feature.geometry.coordinates as MultiPolygonCoordinates);
84	
85	  return polygons.reduce<GeoCoordinate[]>((largestRing, polygon) => {
86	    const outerRing = polygon[0] ?? [];
87	
88	    if (outerRing.length === 0) {
89	      return largestRing;
90	    }
91	
92	    if (largestRing.length === 0) {
93	      return outerRing;
94	    }
95	
96	    return Math.abs(getRingArea(outerRing)) > Math.abs(getRingArea(largestRing))
97	      ? outerRing
98	      : largestRing;
99	  }, []);
100	}
101	
102	function getCountryCenter(feature: CountryFeature) {
103	  const ring = getLargestRing(feature);
104	
105	  if (ring.length < 3) {
106	    return { lat: 0, lng: 0 };
107	  }
108	
109	  let centroidX = 0;
110	  let centroidY = 0;
111	  let areaAccumulator = 0;
112	
113	  for (let index = 0; index < ring.length; index += 1) {
114	    const [x1, y1] = ring[index];
115	    const [x2, y2] = ring[(index + 1) % ring.length];
116	    const crossProduct = x1 * y2 - x2 * y1;
117	
118	    areaAccumulator += crossProduct;
119	    centroidX += (x1 + x2) * crossProduct;
120	    centroidY += (y1 + y2) * crossProduct;
121	  }
122	
123	  if (areaAccumulator === 0) {
124	    const [lng, lat] = ring[0];
125	    return { lat, lng };
126	  }
127	
128	  const area = areaAccumulator / 2;
129	
130	  return {
131	    lng: centroidX / (6 * area),
132	    lat: centroidY / (6 * area)
133	  };
134	}
135	
136	const countryLabels: CountryLabel[] = countries.map((feature) => {
137	  const { lat, lng } = getCountryCenter(feature);
138	  const name = getCountryName(feature);
139	  const iso_a3 = getCountryCode(feature);
140	  const nameLength = name.length;
141	  const size =
142	    nameLength > 18 ? 0.54 : nameLength > 12 ? 0.68 : nameLength > 8 ? 0.8 : 0.92;
143	
144	  return {
145	    lat,
146	    lng,
147	    name,
148	    iso_a3,
149	    size
150	  };
151	});
