3	import { useCallback, useEffect, useRef, useState } from "react";
4	import * as THREE from "three";
5	
6	export type PanoramaViewerProps = {
7	  mediaType: "image" | "video";
8	  src: string;
9	  title?: string;
10	  initialYaw?: number;
11	  initialPitch?: number;
12	};
13	
14	type ViewState = {
15	  yaw: number;
16	  pitch: number;
17	  fov: number;
18	};
19	
20	const MIN_FOV = 35;
21	const MAX_FOV = 90;
22	
23	function formatTime(value: number) {
24	  if (!Number.isFinite(value)) {
25	    return "0:00";
26	  }
27	
28	  const minutes = Math.floor(value / 60);
29	  const seconds = Math.floor(value % 60)
30	    .toString()
31	    .padStart(2, "0");
32	
33	  return `${minutes}:${seconds}`;
34	}
35	
36	export function PanoramaViewer({
37	  mediaType,
38	  src,
39	  title = "360 degree panorama",
40	  initialYaw = 0,
41	  initialPitch = 0
42	}: PanoramaViewerProps) {
43	  const containerRef = useRef<HTMLDivElement | null>(null);
44	  const mountRef = useRef<HTMLDivElement | null>(null);
45	  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
46	  const videoRef = useRef<HTMLVideoElement | null>(null);
47	  const viewRef = useRef<ViewState>({ yaw: initialYaw, pitch: initialPitch, fov: 75 });
48	  const [isLoading, setIsLoading] = useState(true);
49	  const [error, setError] = useState<string | null>(null);
50	  const [isPlaying, setIsPlaying] = useState(false);
51	  const [isMuted, setIsMuted] = useState(true);
52	  const [currentTime, setCurrentTime] = useState(0);
53	  const [duration, setDuration] = useState(0);
54	  const [isFullscreen, setIsFullscreen] = useState(false);
55	
56	  const updateFov = useCallback((nextFov: number) => {
57	    const fov = THREE.MathUtils.clamp(nextFov, MIN_FOV, MAX_FOV);
58	    viewRef.current.fov = fov;
59	
60	    if (cameraRef.current) {
61	      cameraRef.current.fov = fov;
62	      cameraRef.current.updateProjectionMatrix();
63	    }
64	  }, []);
65	
66	  const resetView = useCallback(() => {
67	    viewRef.current.yaw = initialYaw;
68	    viewRef.current.pitch = initialPitch;
69	    updateFov(75);
70	  }, [initialPitch, initialYaw, updateFov]);
71	
72	  useEffect(() => {
73	    const mount = mountRef.current;
74	    if (!mount) {
75	      return;
76	    }
77	
78	    setIsLoading(true);
79	    setError(null);
80	    setCurrentTime(0);
81	    setDuration(0);
82	    setIsPlaying(false);
83	    viewRef.current = { yaw: initialYaw, pitch: initialPitch, fov: 75 };
84	
85	    const scene = new THREE.Scene();
86	    const camera = new THREE.PerspectiveCamera(75, 1, 0.1, 1100);
87	    cameraRef.current = camera;
88	
89	    const renderer = new THREE.WebGLRenderer({ antialias: true });
90	    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
91	    renderer.outputEncoding = THREE.sRGBEncoding;
92	    renderer.domElement.setAttribute("aria-label", `${title}. Drag to look around.`);
93	    renderer.domElement.setAttribute("role", "img");
94	    renderer.domElement.style.display = "block";
95	    renderer.domElement.style.height = "100%";
96	    renderer.domElement.style.width = "100%";
97	    renderer.domElement.style.cursor = "grab";
98	    renderer.domElement.style.touchAction = "none";
99	    mount.appendChild(renderer.domElement);
100	
101	    const geometry = new THREE.SphereGeometry(500, 64, 40);
102	    geometry.scale(-1, 1, 1);
103	    const material = new THREE.MeshBasicMaterial({ color: 0xffffff });
104	    const mesh = new THREE.Mesh(geometry, material);
105	    scene.add(mesh);
106	
107	    let texture: THREE.Texture | null = null;
108	    let video: HTMLVideoElement | null = null;
109	    let frameId = 0;
110	    let disposed = false;
111	
112	    if (mediaType === "image") {
113	      new THREE.TextureLoader().load(
114	        src,
115	        (loadedTexture) => {
116	          if (disposed) {
117	            loadedTexture.dispose();
118	            return;
119	          }
120	
121	          texture = loadedTexture;
122	          texture.encoding = THREE.sRGBEncoding;
123	          material.map = texture;
124	          material.needsUpdate = true;
125	          setIsLoading(false);
126	        },
127	        undefined,
128	        () => {
129	          if (!disposed) {
130	            setError("The panorama image could not be loaded.");
131	            setIsLoading(false);
132	          }
133	        }
134	      );
135	    } else {
136	      video = document.createElement("video");
137	      videoRef.current = video;
138	      video.src = src;
139	      video.crossOrigin = "anonymous";
140	      video.loop = true;
141	      video.muted = true;
142	      video.playsInline = true;
143	      video.preload = "metadata";
144	
145	      texture = new THREE.VideoTexture(video);
146	      texture.encoding = THREE.sRGBEncoding;
147	      texture.minFilter = THREE.LinearFilter;
148	      texture.magFilter = THREE.LinearFilter;
149	      material.map = texture;
150	      material.needsUpdate = true;
151	
152	      const handleCanPlay = () => {
153	        if (disposed) {
154	          return;
155	        }
156	
157	        setIsLoading(false);
158	        void video?.play().then(() => setIsPlaying(true)).catch(() => setIsPlaying(false));
159	      };
160	      const handleMetadata = () => setDuration(video?.duration ?? 0);
161	      const handleTimeUpdate = () => setCurrentTime(video?.currentTime ?? 0);
162	      const handlePlay = () => setIsPlaying(true);
163	      const handlePause = () => setIsPlaying(false);
164	      const handleError = () => {
165	        setError("This browser could not play the panorama video.");
166	        setIsLoading(false);
167	      };
168	
169	      video.addEventListener("canplay", handleCanPlay, { once: true });
170	      video.addEventListener("loadedmetadata", handleMetadata);
171	      video.addEventListener("timeupdate", handleTimeUpdate);
172	      video.addEventListener("play", handlePlay);
173	      video.addEventListener("pause", handlePause);
174	      video.addEventListener("error", handleError);
175	      video.load();
176	    }
177	
178	    const pointers = new Map<number, { x: number; y: number }>();
179	    let dragStart: { x: number; y: number; yaw: number; pitch: number } | null = null;
180	    let pinchStart: { distance: number; fov: number } | null = null;
181	
182	    function pointerDistance() {
183	      const values = Array.from(pointers.values());
184	      if (values.length < 2) {
185	        return 0;
186	      }
187	      return Math.hypot(values[0].x - values[1].x, values[0].y - values[1].y);
188	    }
189	
190	    function handlePointerDown(event: PointerEvent) {
191	      renderer.domElement.setPointerCapture(event.pointerId);
192	      pointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
193	      renderer.domElement.style.cursor = "grabbing";
194	
195	      if (pointers.size === 1) {
196	        dragStart = {
197	          x: event.clientX,
198	          y: event.clientY,
199	          yaw: viewRef.current.yaw,
200	          pitch: viewRef.current.pitch
201	        };
202	      } else if (pointers.size === 2) {
203	        pinchStart = { distance: pointerDistance(), fov: viewRef.current.fov };
204	      }
205	    }
206	
207	    function handlePointerMove(event: PointerEvent) {
208	      if (!pointers.has(event.pointerId)) {
209	        return;
210	      }
211	
212	      pointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
213	
214	      if (pointers.size === 2 && pinchStart) {
215	        const distance = pointerDistance();
216	        if (distance > 0) {
217	          updateFov(pinchStart.fov * (pinchStart.distance / distance));
218	        }
219	        return;
220	      }
221	
222	      if (pointers.size === 1 && dragStart) {
223	        viewRef.current.yaw = dragStart.yaw + (dragStart.x - event.clientX) * 0.12;
224	        viewRef.current.pitch = THREE.MathUtils.clamp(
225	          dragStart.pitch + (event.clientY - dragStart.y) * 0.12,
226	          -85,
227	          85
228	        );
229	      }
230	    }
231	
232	    function handlePointerUp(event: PointerEvent) {
233	      pointers.delete(event.pointerId);
234	      renderer.domElement.style.cursor = pointers.size ? "grabbing" : "grab";
235	      dragStart = null;
236	      pinchStart = null;
237	
238	      const remaining = Array.from(pointers.values())[0];
239	      if (remaining) {
240	        dragStart = {
241	          x: remaining.x,
242	          y: remaining.y,
243	          yaw: viewRef.current.yaw,
244	          pitch: viewRef.current.pitch
245	        };
246	      }
247	    }
248	
249	    function handleWheel(event: WheelEvent) {
250	      event.preventDefault();
